@font-face{font-family:'Source Sans 3';font-style:normal;font-weight:300;font-display:block;src:url('data:font/ttf;base64,') format('truetype')}
@font-face{font-family:'Source Sans 3';font-style:normal;font-weight:400;font-display:block;src:url('data:font/ttf;base64,') format('truetype')}
@font-face{font-family:'Source Sans 3';font-style:normal;font-weight:500;font-display:block;src:url('data:font/ttf;base64,') format('truetype')}
@font-face{font-family:'Source Sans 3';font-style:normal;font-weight:600;font-display:block;src:url('data:font/ttf;base64,') format('truetype')}
