/* One sidebar component for personal pages and every notes format. */
.side-rail{padding:34px 28px;font-family:'Source Sans 3',system-ui,-apple-system,BlinkMacSystemFont,sans-serif;font-size:16px;font-weight:400;line-height:1.65;letter-spacing:normal;color:#fff8f5;overflow-wrap:normal;word-break:normal}
#rail-content{display:contents;min-height:0}
.side-rail .rail-brand{display:block;margin:0;padding:0 0 20px;border-bottom:1px solid rgba(255,255,255,.22);font-family:'Libre Baskerville',Georgia,serif;font-size:23px;font-weight:400;line-height:1.2;letter-spacing:.01em;text-decoration:none;color:#fff8f5}
.side-rail .rail-brand span{font:inherit;letter-spacing:inherit}
.side-rail .rail-brand:hover{color:#fff}
.side-rail .rail-subtitle{display:block;margin:10px 0 0;padding:0;font-size:12px;font-weight:400;line-height:1.5;letter-spacing:normal;color:rgba(255,255,255,.70)}
.side-rail .rail-subtitle a{color:inherit;text-decoration:none;border-bottom:1px solid rgba(255,255,255,.32)}
.side-rail .rail-footer{margin-top:auto;padding:18px 0 0;border-top:1px solid rgba(255,255,255,.18);font-size:12px;font-weight:400;line-height:1.65;letter-spacing:normal;color:rgba(255,255,255,.68);overflow-wrap:anywhere}
.side-rail .rail-footer::before{content:none}
.side-rail .rail-footer a{color:inherit;text-decoration:none}
.rail-groups{display:grid;gap:9px;margin:24px 0 18px}
.rail-group{min-width:0;border-top:1px solid #ffffff26;padding-top:5px}
.rail-group>summary,.rail-part>summary{display:flex;align-items:baseline;justify-content:space-between;gap:12px;list-style:none;cursor:pointer;color:#fff8f5c9;text-transform:none;letter-spacing:.025em}
.rail-group>summary{padding:9px 0;font:600 13px/1.7 'Source Sans 3',sans-serif}
.rail-group.is-current>summary{color:#fff8f5}
.rail-group>summary::-webkit-details-marker,.rail-part>summary::-webkit-details-marker{display:none}
.rail-group>summary::after,.rail-part>summary::after{content:'+';flex-shrink:0;color:#e0c28d;font-size:16px;font-weight:400}
.rail-group[open]>summary::after,.rail-part[open]>summary::after{content:'−'}
.rail-group>summary:focus-visible,.rail-part>summary:focus-visible{outline:2px solid #e0c28d;outline-offset:3px}
.rail-group .rail-nav{display:flex;flex-direction:column;gap:2px;margin:0 0 10px;padding-left:8px}
.side-rail .rail-group .rail-nav a{display:block;padding:6px 6px 6px 10px;border-left:2px solid transparent;font-size:12px;font-weight:400;line-height:1.75;letter-spacing:.02em;text-transform:none;text-decoration:none;color:rgba(255,255,255,.76)}
.side-rail .rail-group .rail-nav a:hover,.side-rail .rail-group .rail-nav a.active{color:#fff;border-left-color:#e0c28d;background:linear-gradient(90deg,#ffffff12,transparent)}
.rail-group>.chapter-nav{display:block;gap:0;margin:0 0 8px 8px;padding:0;list-style:none}
.rail-part>summary{padding:10px 0 7px;font:600 11px/1.7 'Source Sans 3',sans-serif}
.rail-part>summary::after{font-size:13px}
.rail-part .chapter-nav{display:grid;gap:2px;margin:0 0 6px 4px;padding:0;list-style:none}
.rail-part .chapter-nav a{display:flex;align-items:baseline;gap:9px;padding:7px 5px 7px 10px;border-left:2px solid transparent;color:#fff8f5bd;font-size:11px;font-weight:400;line-height:1.65;letter-spacing:normal;text-decoration:none}
.rail-part .chapter-nav a.active{font-weight:600}
.rail-part .chapter-nav a:hover,.rail-part .chapter-nav a.active{color:#fff;border-left-color:#e0c28d;background:linear-gradient(90deg,#ffffff12,transparent)}
.rail-part .chapter-nav a .chapter-no{flex:0 0 24px;min-width:24px;white-space:nowrap;overflow-wrap:normal;word-break:normal;font-variant-numeric:tabular-nums;font-size:11px;font-family:Georgia,serif;color:#e0c28d}
body:not([data-page]) .side-rail{overflow-y:auto;scrollbar-width:thin;scrollbar-color:#9c6570 transparent}
@media(max-width:900px){.side-rail{padding:22px}.side-rail .rail-brand{border-bottom:none;padding-bottom:6px}.side-rail .rail-footer{display:none}}
@media(max-width:760px){body:not([data-page]) .side-rail{overflow:visible;height:auto}.rail-groups{margin:20px 0 15px}.rail-group .rail-nav{flex-direction:column;flex-wrap:nowrap}}
